const express = require('express');
const Y = require('yjs');
const redis = require('../redis');
const db = require('../db');

const app = express();

app.get('/api/whiteboards/:boardId/crdt-state', async (req, res) => {
  const { boardId } = req.params;

  // Validate user has view permissions on the requested whiteboard
  const board = await db('whiteboards')
    .where({ id: boardId, workspace_id: req.user.workspaceId })
    .first();

  if (!board) {
    return res.status(404).json({ error: 'Whiteboard not found or access denied' });
  }

  const rawState = await redis.getBuffer(`whiteboard:${boardId}:state`);
  if (!rawState) {
    return res.status(404).json({ error: 'Whiteboard state not found' });
  }

  res.setHeader('Content-Type', 'application/octet-stream');
  return res.send(rawState);
});

module.exports = app;
